#include <stdio.h>
int main(void) {
    int a[6] = {4, 8, 15, 16, 23, 42}, x = 15, idx = -1;
    for (int i = 0; i < 6; i++)
        if (a[i] == x) { idx = i; break; }
    printf("%d\n", idx);
    return 0;
}

