#include <stdio.h>
int main(void) {
    int a[6] = {1, 3, 5, 7, 9, 11}, x = 7, lo = 0, hi = 5;
    while (lo <= hi) {
        int mid = (lo + hi) / 2;
        if (a[mid] == x) { printf("%d\n", mid); return 0; }
        if (a[mid] < x) lo = mid + 1; else hi = mid - 1;
    }
    printf("-1\n");
    return 0;
}

#include <stdio.h>
int main(void) {
    int a[5] = {1, 2, 2, 2, 3}, x = 2, lo = 0, hi = 4, ans = -1;
    while (lo <= hi) {
        int mid = (lo + hi) / 2;
        if (a[mid] == x) { ans = mid; hi = mid - 1; }
        else if (a[mid] < x) lo = mid + 1; else hi = mid - 1;
    }
    printf("%d\n", ans);
    return 0;
}

#include <stdio.h>
int main(void) {
    int a[5] = {1, 3, 5, 7, 9}, x = 9, lo = 0, hi = 4;
    while (lo < hi) {
        int mid = (lo + hi) / 2;
        if (a[mid] == x) { printf("found\n"); return 0; }
        if (a[mid] < x) lo = mid + 1; else hi = mid - 1;
    }
    printf("not found\n");
